    "description": "১. এই পোর্টেবল জুসারের ধারণক্ষমতা বা ক্যাপাসিটি কত? উত্তর: এর জুস জারটির ধারণক্ষমতা হলো মি (420ml), যা একবারে একজনের জন্য পারফেক্ট এক গ্লাস ফ্রেশ জুস তৈরির জন্য যথেষ্ট। ২. এটি ফুল চার্জে কতক্ষণ চলে এবং ব্যাটারি ক্যাপাসিটি কত? উত্তর: এতে রয়েছে ১২০০mAh (1200mAh) শক্তিশালী রিচার্জেবল ব্যাটারি। এটি একবার ফুল চার্জ করার পর বেশ কয়েকবার জুস বা স্মুদি তৈরি করতে পারবেন। ৩. জুসারটি চার্জ করার নিয়ম কী? এর সাথে কি চার্জার দেওয়া থাকে? উত্তর: এটি চার্জ করা অত্যন্ত সহজ। বক্সে একটি ইউএসবি (USB) চার্জিং ক্যাবল দেওয়া থাকে। এটি ৫ ভোল্ট (5V, 1A) চার্জিং ভোল্টেজ সাপোর্ট করে, যার ফলে আপনি এটি মোবাইল চার্জার, পাওয়ার ব্যাংক কিংবা ল্যাপটপ দিয়েও অনায়াসে চার্জ করতে পারবেন। ৪. এর মোটর পাওয়ার বা কার্যক্ষমতা কেমন? উত্তর: এটি ছোট ও পোর্টেবল হলেও এর রেটেড পাওয়ার হলো ৪০ ওয়াট (40W) এবং রেটেড ভোল্টেজ ৩.৭ ভোল্ট (3.7V)। এর শক্তিশালী ব্লেড ও মোটর যেকোনো নরম ফল, মিল্কশেক বা প্রোটিন শেক খুব দ্রুত ও নিখুঁতভাবে ব্লেন্ড করতে পারে। ৫. প্রোডাক্টটির সাইজ কেমন? ব্যাগে কি সহজে নেওয়া যাবে? উত্তর: হ্যাঁ, এটি খুবই কম্প্যাক্ট ও লাইটওয়েট। এর প্যাকেজ সাইজ মাত্র ৮০ x ৮০ x ২২৩ মিমি। সাধারণ পানির বোতলের মতোই এটি যেকোনো ট্রাভেল ব্যাগ বা ব্যাকপ্যাকে খুব অল্প জায়গায় ক্যারি করা যায়। ✨ কেন এই Portable Juicer-টি আপনার লাইফস্টাইলের অংশ হওয়া উচিত? ইনস্ট্যান্ট ফ্রেশ জুস: প্রিজারভেটিভ যুক্ত বাজারের জুস বাদ দিয়ে যেকোনো সময় চোখের সামনে ফ্রেশ ফল দিয়ে পুষ্টিকর জুস বানিয়ে নিন। সহজ পরিষ্কার পদ্ধতি: জুস তৈরি শেষে এতে সামান্য পানি ও ডিটারজেন্ট দিয়ে ব্লেন্ডারটি অন করলেই এটি নিজে নিজেই ভেতরের ব্লেড পরিষ্কার করে নেয়। মাল্টি-ফাংশনাল: শুধু জুস নয়, এটি দিয়ে বেবি ফুড পিউরি, আইসড কফি, প্রোটিন শেক এবং বিভিন্ন ডিটক্স ড্রিংকস তৈরি করা সম্ভব।",
