    "updatedAt": "2026-09-10T00:00:00.000Z",
    "description": "রান্না আর স্টিমিং একসাথে—ঝটপট ও পুষ্টিকর রান্নার জন্য আপনার কিচেনের অল-ইন-ওয়ান সঙ্গী! ব্যস্ত লাইফস্টাইলে রান্নার কাজকে সহজ ও ঝামেলাহীন করতে Prestige Multifunctional Cooker একটি চমৎকার গ্যাজেট। ২.০ লিটার ধারণক্ষমতার এই কুকারটিতে ভাত রান্না, তরকারি, স্যুপ, নুডলস বা পাস্তা তৈরির পাশাপাশি উপরের স্টিমার বাস্কেটে খুব সহজে মোমো, ডিম, বা সবজি স্টিম (ভাপানো) করে নেওয়া যায়। ১০০০ ওয়াটের শক্তিশালী পারফরম্যান্সের সাথে এর নন-স্টিক কোটিং রান্নার অভিজ্ঞতাকে করবে আরও আরামদায়ক। ❓ FAQ - প্রায়শই জিজ্ঞাসিত প্রশ্নাবলী (Frequently Asked Questions) ১. এই মাল্টিফাংশনাল কুকারটির ধারণক্ষমতা বা ক্যাপাসিটি কত? উত্তর: এই Prestige ইলেকট্রিক কুকারটির ধারণক্ষমতা হলো ২.০ লিটার (2.0 Litre), যা একটি ছোট বা মাঝারি পরিবারের প্রতিদিনের রান্নার জন্য একদম পারফেক্ট। ২. এর ভেতরের পট বা পাত্রটি কি নন-স্টিক? উত্তর: হ্যাঁ, এর ভেতরের পাত্রটি প্রিমিয়াম Non-stick Coated Inner Pot। ফলে রান্না করার সময় খাবার নিচে লেগে বা পুড়ে যায় না এবং রান্নার পর এটি পরিষ্কার করা অত্যন্ত সহজ। ৩. খাবার কি রান্নার পর দীর্ঘক্ষণ গরম রাখা যাবে? উত্তর: অবশ্যই। এতে রয়েছে অটোমেটিক With warmer function (ওয়ার্মার ফিচার)। রান্না শেষ হওয়ার পর এটি স্বয়ংক্রিয়ভাবে খাবারকে দীর্ঘক্ষণ গরম ও ফ্রেশ রাখে। ৪. এটি কত ওয়াটের এবং এর কার্যক্ষমতা কেমন? উত্তর: এটি একটি 1000 WATTS (১০০০ ওয়াট)-এর অত্যন্ত শক্তিশালী কুকার। উচ্চ ওয়াটের কারণে এটি খুব দ্রুত গরম হয় এবং অল্প সময়ে নিখুঁতভাবে রান্না সম্পন্ন করে আপনার সময় ও বিদ্যুৎ সাশ্রয় করে। ৫. এই কুকারটি দিয়ে একসাথে কী কী কাজ করা সম্ভব? উত্তর: এটি একটি Multifunctional Cooker with Steamer। এর নিচের পাত্রে আপনি যেকোনো কিছু রান্না করতে পারবেন এবং একই সময়ে উপরের স্টিমারে মোমো, পিঠা, সবজি, মাংস বা ডিম ভাপিয়ে নিতে পারবেন। ৬. প্যাকেজের সাথে কী কী ফ্রি অ্যাক্সেসরিজ পাওয়া যাবে? উত্তর: মূল কুকার ও স্টিমারের সাথে প্যাকেজে রান্নার জন্য একটি প্লাস্টিক স্পুন (চামচ), একটি মেজারিং কাপ (মাপার পট) এবং পাওয়ার কর্ড সম্পূর্ণ Free বা অন্তর্ভুক্ত হিসেবে দেওয়া থাকে। ✨ কেন Prestige মাল্টিফাংশনাল কুকারটি আপনার রান্নাঘরে থাকা দরকার? হেলদি কুকিং: এর ফুড-গ্রেড স্টিমার বাস্কেটের সাহায্যে তেল ছাড়াই পুষ্টিকর এবং তেলমুক্ত স্টিমড খাবার তৈরি করা যায়। সহজ ও নিরাপদ ব্যবহার: কুকারটিতে ওয়ান-বাটন কন্ট্রোল সিস্টেম এবং ইন্ডিকেটর লাইট রয়েছে, যা রান্না করাকে করে তোলে সম্পূর্ণ নিরাপদ। স্টাইলিশ ও কমপ্যাক্ট ডিজাইন: এর আকর্ষণীয় পেস্টল গ্রিন কালার এবং আধুনিক কমপ্যাক্ট লুক আপনার ডাইনিং টেবিল বা কিচেন কাউন্টারের সৌন্দর্য বহুগুণ বাড়িয়ে দেবে।",
